const data = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/);
const n = BigInt(data[0]);
const sx = BigInt(data[1]);
const sy = BigInt(data[2]);
const dx0 = BigInt(data[3]);
const dy0 = BigInt(data[4]);
let t = BigInt(data[5]);

const md = (a) => ((a % n) + n) % n;

const SZ = 6;

function mul(A, B) {
  const C = [];
  for (let i = 0; i < SZ; i++) {
    const row = new Array(SZ).fill(0n);
    for (let k = 0; k < SZ; k++) {
      const a = A[i][k];
      if (a === 0n) continue;
      for (let j = 0; j < SZ; j++) {
        row[j] = (row[j] + a * B[k][j]) % n;
      }
    }
    C.push(row);
  }
  return C;
}

function identity() {
  const I = [];
  for (let i = 0; i < SZ; i++) {
    const row = new Array(SZ).fill(0n);
    row[i] = 1n % n;
    I.push(row);
  }
  return I;
}

// state: [X, Y, dx, dy, i, 1]
let M = [
  [2n, 1n, 1n, 0n, 1n, 2n],
  [1n, 2n, 0n, 1n, 1n, 2n],
  [1n, 1n, 1n, 0n, 1n, 2n],
  [1n, 1n, 0n, 1n, 1n, 2n],
  [0n, 0n, 0n, 0n, 1n, 1n],
  [0n, 0n, 0n, 0n, 0n, 1n]
];

for (let i = 0; i < SZ; i++)
  for (let j = 0; j < SZ; j++)
    M[i][j] = md(M[i][j]);

let R = identity();
while (t > 0n) {
  if (t & 1n) R = mul(R, M);
  M = mul(M, M);
  t >>= 1n;
}

const v = [md(sx - 1n), md(sy - 1n), md(dx0), md(dy0), 0n, 1n % n];
const res = new Array(SZ).fill(0n);
for (let i = 0; i < SZ; i++) {
  let s = 0n;
  for (let j = 0; j < SZ; j++) {
    s = (s + R[i][j] * v[j]) % n;
  }
  res[i] = s;
}

console.log((md(res[0]) + 1n).toString() + " " + (md(res[1]) + 1n).toString());
